sys_script_include.script:
var MSS_Collateral_XMatter_ITID_WidgetFailureHandler = Class.create();
MSS_Collateral_XMatter_ITID_WidgetFailureHandler.prototype = {
    initialize: function() {},

    createITIDEvent: function(severity, text, object) {
        try {
            var parm2 = object + '|' + severity;
            gs.eventQueue('x_hsb11_mss_coll_0.Collateral_Send_ITID_', current, text, parm2);
        } catch (error) {
            gs.error("Collateral - Script Include - MSS_Collateral_XMatter_ITID_WidgetFailureHandler Unknow Error: " + error.message);
        }

    },

    type: 'MSS_Collateral_XMatter_ITID_WidgetFailureHandler'
};
